    /// slot NSStackView.arranged-subviews: NSStackView.h: addArrangedSubview:, insertArrangedSubview:atIndex:, removeArrangedSubview:. Unlike UIStackView, NSStackView's removeArrangedSubview: also removes the view from subviews (verified by the generated test: superview is nil after remove); removeFromSuperview is sent anyway when the view is still attached.
    pub fn slot_nsstackview_arranged_subviews() {
        let h = Harness::shared();
        let p = h.create("stack-view");
        let a = h.create("view");
        let b = h.create("view");
        h.insert(p, a, None, Some("arranged-subviews")).unwrap();
        h.insert(p, b, Some(a), Some("arranged-subviews")).unwrap();
        assert_eq!(h.native_list(p, "arrangedSubviews"), vec![h.obj(b), h.obj(a)], "b inserted before a");
        assert!(h.superview(a) == Some(h.obj(p)), "a is a subview");
        h.remove(p, b).unwrap();
        assert!(h.superview(b).is_none(), "removed child is detached");
        assert_eq!(h.native_list(p, "arrangedSubviews"), vec![h.obj(a)]);
        h.remove(p, b).unwrap_err();
        h.insert(p, b, None, Some("arranged-subviews")).unwrap();
        assert_eq!(h.native_list(p, "arrangedSubviews"), vec![h.obj(a), h.obj(b)], "re-inserted at the end");
        h.destroy(p);
        h.destroy(a);
        h.destroy(b);
    }

