    /// slot NSWindow.content-view: NSWindow.contentView (strong, nullable). The window retains its content view; replacing it releases the old one but does not destroy it while we hold a handle. Clearing installs a fresh NSView so the window keeps a valid content view.
    pub fn slot_nswindow_content_view() {
        let h = Harness::shared();
        let p = h.create("window");
        let a = h.create("view");
        let b = h.create("view");
        h.insert(p, a, None, Some("content-view")).unwrap();
        assert!(h.native_get(p, "contentView") == Some(h.obj(a)), "a set");
        h.insert(p, b, None, Some("content-view")).unwrap();
        assert!(h.native_get(p, "contentView") == Some(h.obj(b)), "b replaces a");
        assert!(h.alive(a), "the replaced child stays alive (handle)");
        h.remove(p, a).unwrap_err();
        h.remove(p, b).unwrap();
        assert!(h.native_get(p, "contentView").is_some_and(|v| v != h.obj(b)), "cleared to a fresh view");
        h.destroy(p);
        h.destroy(a);
        h.destroy(b);
    }

    /// signal NSWindow.window-should-close (delegate): NSWindowDelegate.windowShouldClose: returns BOOL, YES = allow. JS stops the close with e.preventDefault() (result true), so the delegate answers NO; no decision = YES. A busy host (JS running) vetoes, like close-request on GTK/Qt (ABI v2.1).
    pub fn signal_nswindow_window_should_close() {
        let h = Harness::shared();
        let w = h.create("window");
        h.call(w, "make-key-and-order-front", vec![]).unwrap();
        h.listen(w, "window-should-close", true).unwrap();
        h.set_sync_reply(V::Bool(true));
        h.perform_close(w);
        assert!(h.alive(w) && h.is_visible(w), "a true result (preventDefault) vetoes the close");
        assert!(h.take_events().iter().any(|e| e.0 == w && e.1 == "window-should-close"), "the handler ran");
        h.set_sync_reply(V::Null);
        h.perform_close(w);
        h.pump(50);
        assert!(!h.alive(w), "no decision lets the window close");
        assert!(h.take_gone().contains(&(w, svelters_abi::SVL_GONE_CLOSED)), "reported closed");
    }

    /// signal NSWindow.window-will-close (delegate): NSWindowDelegate.windowWillClose: (also NSWindowWillCloseNotification). The backend reports the window SVL_GONE_CLOSED after this, listened or not.
    pub fn signal_nswindow_window_will_close() {
        let h = Harness::shared();
        let w = h.create("window");
        h.call(w, "make-key-and-order-front", vec![]).unwrap();
        h.listen(w, "window-will-close", true).unwrap();
        h.close_window(w);
        h.pump(50);
        assert!(h.take_events().iter().any(|e| e.0 == w && e.1 == "window-will-close"), "posted");
        assert!(h.take_gone().contains(&(w, svelters_abi::SVL_GONE_CLOSED)), "reported closed");
    }

